import requests

def fetch(client, url):
    try:
        return client.get(url, timeout=30)
    except requests.exceptions.Timeout as e:
        raise e
    except requests.exceptions.RequestException as e:
        raise e

import requests_mock
from fetcher import fetch
import pytest

# Mock client to simulate requests behavior
def mock_client():
    class MockClient:
        def get(self, url, timeout=None):
            if timeout is None:
                raise ValueError("Timeout must be specified for testing")
            return {"data": "success", "timeout_used": timeout}
    return MockClient()


@requests_mock.Mocker()
def test_timeout_set(mock):
    mock.get("https://example.com", text="Success", status_code=200)
    client = mock.client

    # Test successful fetch with timeout
    result = fetch(client, "https://example.com")
    assert result.status_code == 200

    # Verify timeout was passed to client.get
    calls = mock.request_history
    assert len(calls) == 1
    assert calls[0].kwargs.get("timeout") == 30


@requests_mock.Mocker()
def test_exception_propagation(mock):
    mock.get("https://example.com", exc=requests.exceptions.Timeout("Request timed out"))
    client = mock.client

    try:
        fetch(client, "https://example.com")
        assert False, "Expected Timeout exception to be raised"
    except requests.exceptions.Timeout:
        pass  # Expected

    # Verify timeout was passed to client.get
    calls = mock.request_history
    assert len(calls) == 1
    assert calls[0].kwargs.get("timeout") == 30


@requests_mock.Mocker()
def test_other_exceptions_propagated(mock):
    mock.get("https://example.com", exc=requests.exceptions.ConnectionError("Connection failed"))
    client = mock.client

    try:
        fetch(client, "https://example.com")
        assert False, "Expected ConnectionError to be propagated"
    except requests.exceptions.ConnectionError:
        pass  # Expected

    # Verify timeout was passed to client.get
    calls = mock.request_history
    assert len(calls) == 1
    assert calls[0].kwargs.get("timeout") == 30
